window.HOEREN_TESTS[88] = {"id":"beim-umzugsunternehmen","name":"Beim Umzugsunternehmen","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist die Umzugsfirma Schnell. Wir kommen am Samstag — aber nicht um 8 Uhr, sondern schon um 7 Uhr. So sind wir vor dem Verkehr da. Bitte sorgen Sie dafür, dass alle Kartons gepackt sind. Halten Sie auch einen Parkplatz für den Lkw frei. Bis Samstag!","gender":"f","q":"Wann kommt die Umzugsfirma?","opts":["Um 7 Uhr.","Um 8 Uhr.","Um 9 Uhr."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Ich ziehe nächsten Monat um und überlege, ob ich eine Firma nehme oder es mit Freunden mache. Eine Firma ist teuer, aber bequem. Mit Freunden ist es billig, aber anstrengend. Was meinst du? Du bist letztens auch umgezogen. Ruf zurück, danke!","gender":"m","q":"Worüber ist Markus unsicher?","opts":["Wohin er zieht.","Wann er umzieht.","Ob er eine Firma nimmt oder Freunde fragt."],"correct":2},{"transcript":"Achtung Kunden: Bitte beschriften Sie alle Kartons. Schreiben Sie drauf, in welches Zimmer sie kommen und was drin ist, nicht nur den Namen und nicht das Datum. Schwere Sachen wie Bücher in kleine Kartons, leichte in große. So geht der Umzug schneller und nichts geht kaputt. Zerbrechliche Sachen bitte extra kennzeichnen. Danke!","gender":"m","q":"Was soll man auf die Kartons schreiben?","opts":["Nur den Namen.","In welches Zimmer sie kommen.","Das Datum."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Hör mal, unser Umzug ist gut gelaufen! Die Firma war pünktlich und sehr vorsichtig mit den Möbeln. Nur ein Glas ist kaputtgegangen, aber das war nicht schlimm. Sie haben sogar den Schrank wieder aufgebaut. Ich kann sie dir empfehlen, wenn du mal umziehst. Bis bald!","gender":"f","q":"Wie war der Umzug für Anna?","opts":["Eine Katastrophe.","Sehr teuer.","Gut gelaufen."],"correct":2},{"transcript":"Liebe Kunden: Wir bieten verschiedene Pakete an. Beim Basis-Paket transportieren wir nur. Beim Komfort-Paket packen wir auch ein und bauen die Möbel ab und wieder auf. Das Komfort-Paket kostet mehr, spart Ihnen aber viel Arbeit und Stress. Fragen Sie nach einem Angebot. Wir beraten Sie gern!","gender":"f","q":"Was ist beim Komfort-Paket dabei?","opts":["Auch Einpacken und Möbel aufbauen.","Nur der Transport.","Nur das Einpacken."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer macht was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Morgen ist der große Tag. Wer macht was bei uns?"},{"speaker":"Lisa","gender":"f","text":"Ich habe einen Zettel an die Tür gehängt. Fünf Sachen müssen fertig werden."},{"speaker":"Lukas","gender":"m","text":"Ich packe die Kartons. In der Küche stehen noch Teller und Tassen."},{"speaker":"Lisa","gender":"f","text":"Schreib bitte Küche oder Zimmer auf den Zettel. Putzt jemand noch die alte Wohnung?"},{"speaker":"Lukas","gender":"m","text":"Putzen machen wir dort nicht. Dazu fehlt heute die Zeit."},{"speaker":"Lisa","gender":"f","text":"Ich trage die schweren Möbel mit zwei Freunden."},{"speaker":"Lukas","gender":"m","text":"Die Treppe ist eng. Tom kennt den Weg gut."},{"speaker":"Lisa","gender":"f","text":"Tom will den Lkw fahren. Er wartet um acht an der Ecke."},{"speaker":"Lukas","gender":"m","text":"Bringt jemand den Müll weg? Der steht noch vor der Tür."},{"speaker":"Lisa","gender":"f","text":"Den Müll bringt heute keiner weg."},{"speaker":"Lukas","gender":"m","text":"Sara baut gern Dinge zusammen."},{"speaker":"Lisa","gender":"f","text":"Sara soll die Möbel aufbauen. Das Bett und der Schrank kommen in das Zimmer."},{"speaker":"Lukas","gender":"m","text":"Ohne sie stehen wir lange. Tim bleibt den ganzen Tag in der Küche."},{"speaker":"Lisa","gender":"f","text":"Tim soll fürs Essen sorgen. Er kocht Suppe und kauft Brot."},{"speaker":"Lukas","gender":"m","text":"Suppe ist genau das Richtige."},{"speaker":"Lisa","gender":"f","text":"Wir fangen mit den Kartons an."}],"options":[{"letter":"a","text":"Müll wegbringen"},{"letter":"b","text":"Fürs Essen sorgen"},{"letter":"c","text":"Möbel aufbauen"},{"letter":"d","text":"Den Lkw fahren"},{"letter":"e","text":"Kinder betreuen"},{"letter":"f","text":"Kartons packen"},{"letter":"g","text":"Parkplatz freihalten"},{"letter":"h","text":"Möbel tragen"},{"letter":"i","text":"Putzen"}],"items":[{"person":"Lukas","correct":"f"},{"person":"Lisa","correct":"h"},{"person":"Tom","correct":"d"},{"person":"Sara","correct":"c"},{"person":"Tim","correct":"b"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, was kostet der Umzug? 600 Euro, oder schon 300?"},{"speaker":"Mitarbeiter","gender":"m","text":"Das Basis-Paket 600 Euro. 300 Euro reicht bei uns nicht, das wäre zu wenig."},{"speaker":"Kundin","gender":"f","text":"Und mit Aufbau? Ist das dann 900 oder bleiben 600?"},{"speaker":"Mitarbeiter","gender":"m","text":"Dann 900 Euro. Nicht 600 und nicht 300, mit Aufbau sind es 900."},{"speaker":"Kundin","gender":"f","text":"Verstehe, dann 900 Euro mit Aufbau. Danke."}],"q":"Was kostet der Umzug mit Aufbau?","opts":["900 Euro.","600 Euro.","300 Euro."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Wie viele Leute kommen? Zwei, drei oder vier?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Drei Männer und ein Lkw. Nicht zwei und nicht vier, drei Leute reichen."},{"speaker":"Mann","gender":"m","text":"Reicht das für eine große Wohnung? Zwei wären zu wenig, oder?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Ja, drei schaffen wir in einem Tag. Nicht zwei und nicht vier, drei sind geplant."},{"speaker":"Mann","gender":"m","text":"Gut, dann drei Leute. Das beruhigt mich."}],"q":"Wie viele Leute kommen zum Umzug?","opts":["Zwei.","Drei.","Vier."],"correct":1},{"lines":[{"speaker":"Frau","gender":"f","text":"Sind die Möbel versichert? Ich frage nicht nach dem Preis und nicht nach der Uhrzeit."},{"speaker":"Mitarbeiter","gender":"m","text":"Ja, falls etwas kaputtgeht. Zum Preis und zum Termin sagen wir später mehr."},{"speaker":"Frau","gender":"f","text":"Auch das teure Klavier? Also wirklich versichert, nicht nur der Preis?"},{"speaker":"Mitarbeiter","gender":"m","text":"Ja, das ist mitversichert. Sie wollten wissen, ob die Möbel versichert sind, und ja, das sind sie."},{"speaker":"Frau","gender":"f","text":"Danke, das ist mir wichtig. Den Preis klären wir danach."}],"q":"Was möchte die Frau wissen?","opts":["Wie viel es kostet.","Ob die Möbel versichert sind.","Wann sie kommen."],"correct":1},{"lines":[{"speaker":"Kunde","gender":"m","text":"Brauchen Sie einen Parkplatz vor dem Haus? Oder einen Aufzug, oder eine Garage?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Ja, einen Parkplatz direkt vor dem Haus. Einen Aufzug und eine Garage brauchen wir nicht."},{"speaker":"Kunde","gender":"m","text":"Wie groß? Reicht eine Garage, oder wirklich der Parkplatz?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Für den Lkw etwa zwei Autolängen, also den Parkplatz. Nicht den Aufzug, nicht die Garage."},{"speaker":"Kunde","gender":"m","text":"Alles klar, ich halte den Parkplatz frei. Danke."}],"q":"Was braucht die Firma vor dem Haus?","opts":["Eine Garage.","Einen Aufzug.","Einen Parkplatz."],"correct":2},{"lines":[{"speaker":"Kundin","gender":"f","text":"Können Sie auch am Sonntag kommen? Oder nur am Freitag?"},{"speaker":"Mitarbeiter","gender":"m","text":"Sonntags arbeiten wir nicht. Freitag geht, aber Samstag auch."},{"speaker":"Kundin","gender":"f","text":"Und am Samstag? Sonntag wirklich nicht, Freitag wäre früh."},{"speaker":"Mitarbeiter","gender":"m","text":"Samstag geht, aber etwas teurer. Nicht am Sonntag, Freitag nur wenn Sie wollen."},{"speaker":"Kundin","gender":"f","text":"Dann nehmen wir Samstag. Danke."}],"q":"An welchem Tag arbeitet die Firma nicht?","opts":["Am Samstag.","Am Freitag.","Am Sonntag."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Stein, dem Chef eines Umzugsunternehmens. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Stein, wann haben Sie am meisten zu tun?"},{"speaker":"Stein","gender":"m","text":"Im Sommer und immer zum Monatsende. Die meisten Mietverträge enden zum Ersten, deshalb ziehen alle gleichzeitig um. An solchen Tagen sind wir komplett ausgebucht. Mein Rat: Wer flexibel ist, sollte mitten im Monat umziehen. Da ist es ruhiger und oft auch günstiger."},{"speaker":"Reporterin","gender":"f","text":"Was machen die Kunden beim Umzug falsch?"},{"speaker":"Stein","gender":"m","text":"Sie unterschätzen, wie viel sie besitzen. Alle sagen: Ich habe nicht viel. Und dann sind es vierzig Kartons. Und sie fangen zu spät mit dem Packen an. Packen Sie früh, Zimmer für Zimmer. Am Umzugstag selbst sollte alles fertig sein, sonst wird es teuer und stressig."},{"speaker":"Reporterin","gender":"f","text":"Ist Ihre Arbeit körperlich sehr hart?"},{"speaker":"Stein","gender":"m","text":"Sehr, schwere Schränke, enge Treppen, oft kein Aufzug. Man braucht Kraft, aber auch Technik. Richtig heben ist wichtig, sonst geht der Rücken kaputt. Meine Leute sind echte Profis. Was für andere unmöglich aussieht, schaffen wir mit der richtigen Methode erstaunlich leicht."},{"speaker":"Reporterin","gender":"f","text":"Geht oft etwas kaputt?"},{"speaker":"Stein","gender":"m","text":"Selten, wir arbeiten sehr vorsichtig. Und alles ist versichert, falls doch mal etwas passiert. Am gefährlichsten sind Spiegel und Glas. Die packen wir besonders gut ein. Wenn ein Kunde später anruft und sich bedankt, weil alles heil ankam, dann habe ich meinen Job gut gemacht."},{"speaker":"Reporterin","gender":"f","text":"Was raten Sie für einen entspannten Umzug?"},{"speaker":"Stein","gender":"m","text":"Planen Sie früh und werfen Sie vorher aus, was Sie nicht brauchen. Warum alten Kram in die neue Wohnung schleppen? Beschriften Sie die Kartons gut. Und sorgen Sie für genug zu trinken und ein gutes Essen, für die Helfer. Mit guter Vorbereitung wird ein Umzug fast schon angenehm."}],"items":[{"q":"Zum Monatsende hat das Unternehmen besonders viel zu tun.","correct":"ja"},{"q":"Herr Stein sagt, die Kunden fangen meist früh genug mit dem Packen an.","correct":"nein"},{"q":"Die Arbeit ist körperlich sehr anstrengend.","correct":"ja"},{"q":"Beim Umzug geht laut ihm sehr häufig etwas kaputt.","correct":"nein"},{"q":"Er rät, vor dem Umzug auszusortieren, was man nicht braucht.","correct":"ja"}]}]};
